import { uniqueStrings } from './unique_base.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const ra = uniqueStrings(a);
console.log('basic:', JSON.stringify(ra));
console.assert(JSON.stringify(ra) === JSON.stringify(['apple','banana','cherry']), 'basic failed');

// Case sensitivity
const b = ['a', 'A', 'a', 'B', 'b'];
const rb = uniqueStrings(b);
console.log('case:', JSON.stringify(rb));
console.assert(JSON.stringify(rb) === JSON.stringify(['a','A','B','b']), 'case failed');

// Whitespace not trimmed
const c = [' x', 'x', ' x', 'x '];
const rc = uniqueStrings(c);
console.log('whitespace:', JSON.stringify(rc));
console.assert(JSON.stringify(rc) === JSON.stringify([' x','x','x ']), 'whitespace failed');

// Input not mutated
const d = ['p', 'q', 'p'];
const snapshot = [...d];
uniqueStrings(d);
console.assert(JSON.stringify(d) === JSON.stringify(snapshot), 'mutation failed');
console.log('no mutation: ok');

// Empty input
console.log('empty:', JSON.stringify(uniqueStrings([])));
console.assert(JSON.stringify(uniqueStrings([])) === '[]', 'empty failed');

// Returns new array (not same reference)
const e = ['z'];
const re = uniqueStrings(e);
console.assert(re !== e, 'not a new array');
console.log('new array: ok');

console.log('ALL CHECKS PASSED');
"

